head.b:skin:
:root{

--primary:#1565C0;

--primary-dark:#0D47A1;

--accent:#FFC107;

--bg:#F5F7FA;

--card:#FFFFFF;

--text:#212121;

--radius:16px;

--shadow:0 10px 25px rgba(0,0,0,.08);

}

*{

margin:0;

padding:0;

box-sizing:border-box;

}

html{

scroll-behavior:smooth;

}

body{

background:var(--bg);

font-family:'Poppins',sans-serif;

color:var(--text);

font-size:16px;

line-height:1.6;

}

img{

max-width:100%;

display:block;

}

a{

text-decoration:none;

color:inherit;

}

.container{

width:94%;

max-width:1280px;

margin:auto;

}

/* HEADER */

.header{

background:var(--primary);

position:sticky;

top:0;

z-index:999;

box-shadow:var(--shadow);

}

.header-wrap{

display:flex;

justify-content:space-between;

align-items:center;

padding:16px 0;

}

.logo{

font-size:30px;

font-weight:700;

color:#fff;

}

.menu{

display:flex;

gap:25px;

}

.menu a{

color:#fff;

font-weight:600;

font-size:15px;

transition:.25s;

}

.menu a:hover{

opacity:.8;

}

/* HERO */

.hero{

background:#fff;

padding:90px 20px;

text-align:center;

}

.hero h1{

font-size:48px;

font-weight:700;

color:var(--primary);

}

.hero p{

margin-top:18px;

font-size:20px;

}

.btn{

display:inline-block;

margin-top:30px;

padding:15px 35px;

border-radius:12px;

font-weight:600;

background:var(--primary);

color:#fff;

}

.btn.secondary{

background:var(--accent);

color:#000;

margin-left:12px;

}

/* SEARCH */

.search-box{

margin:40px auto;

}

.search-box input{

width:100%;

padding:18px;

border-radius:12px;

border:1px solid #ddd;

font-size:17px;

}

/* ADSENSE */

.ads-box{

margin:35px auto;

padding:25px;

background:#fff;

border:2px dashed #ccc;

text-align:center;

}

/* CLASS GRID */

.class-grid{

display:grid;

grid-template-columns:repeat(auto-fit,minmax(180px,1fr));

gap:20px;

margin:35px 0;

}

.class-card{

background:#fff;

padding:28px;

text-align:center;

border-radius:16px;

box-shadow:var(--shadow);

font-weight:600;

transition:.25s;

}

.class-card:hover{

transform:translateY(-6px);

background:var(--primary);

color:#fff;

}

/* MOBILE */

@media(max-width:768px){

.header-wrap{

flex-direction:column;

}

.menu{

flex-wrap:wrap;

justify-content:center;

gap:14px;

}

.hero h1{

font-size:34px;

}

.hero p{

font-size:17px;

}

}
